cat > bot.mjs <<'EOF'
// Proactive-message gate. Decides; never sends.
// Chosen numbers: MIN_CONFIDENCE 0.6, MIN_DATA_POINTS 3,
// HOUR_MIN_SAMPLES 5, HOUR_MAX_DISMISS_SHARE 0.7.
const MIN_CONFIDENCE = 0.6;
const MIN_DATA_POINTS = 3;
const HOUR_MIN_SAMPLES = 5;
const HOUR_MAX_DISMISS_SHARE = 0.7;

const isNum = (v) => typeof v === 'number' && Number.isFinite(v);
const none = (reason, extra = {}) => ({ send: false, surfaces: [], reason, ...extra });

export async function decide({ user, candidate, context, now } = {}) {
  const dir = process.env.STATE_DIR;
  if (!dir) return none('Held: no state directory is configured, so repeats cannot be checked.');
  const t = now instanceof Date ? now.getTime() : NaN;
  if (!Number.isFinite(t)) return none('Held: the current time is unknown.');
  if (!user || typeof user.id !== 'string' || !user.id) return none('Held: the user is unknown.');
  if (!candidate || candidate.id == null || !candidate.insight) return none('Held: the message has no id or insight.');
  if (!context || typeof context.crisis !== 'boolean') return none('Held: it is unknown whether the user is in a crisis.');
  const zone = user.timezone;
  if (typeof zone !== 'string' || !gkZoneOk(zone)) return none('Held: the time zone is unknown or invalid, so local time cannot be checked.');

  const uid = encodeURIComponent(user.id);
  const idKey = `msg-${uid}-${encodeURIComponent(String(candidate.id))}`;

  // Redelivery: same message id gets the same answer; nothing is spent twice.
  const prior = gkRead(dir, idKey);
  if (prior && prior.result) return prior.result;

  // Crisis beats everything.
  if (context.crisis) return none('Nothing shown: the user is in a crisis, so proactive messages stay quiet.');

  const ins = candidate.insight;
  if (typeof ins.key !== 'string' || !ins.key) return none('Held: the finding has no key.');
  if (!isNum(ins.confidence) || !isNum(ins.dataPoints)) return none('Nothing shown: the finding has no confidence or data count, so it is not known to be useful.');
  if (ins.dataPoints < MIN_DATA_POINTS) return none(`Nothing shown: the finding rests on only ${ins.dataPoints} observations (minimum ${MIN_DATA_POINTS}).`);
  if (ins.confidence < MIN_CONFIDENCE) return none(`Nothing shown: confidence ${ins.confidence} is below ${MIN_CONFIDENCE}.`);

  const day = gkDayKey(t, zone);
  const findKey = `find-${uid}-${encodeURIComponent(ins.key)}-${day}`;
  const nextDay = gkNextMidnight(t, zone);
  const repeat = () => none(`Nothing shown: this finding was already shown today; it can come back at ${gkFmt(nextDay, zone)}.`, { nextAllowedAt: nextDay });
  if (gkRead(dir, findKey)) return repeat();

  // Surfaces. In-app is silent; push is the interrupting one.
  const surfaces = ['inApp'];
  let pushOk = true;
  if (typeof user.focusMode !== 'boolean' || user.focusMode) pushOk = false;
  if (pushOk) {
    const h = context.hourStats && context.hourStats[String(gkLocal(t, zone).hh)];
    if (h && isNum(h.acted) && isNum(h.dismissed)) {
      const total = h.acted + h.dismissed;
      if (total >= HOUR_MIN_SAMPLES && h.dismissed / total > HOUR_MAX_DISMISS_SHARE) pushOk = false;
    }
  }
  if (pushOk) surfaces.unshift('push');

  // Claim message id, then the finding for today.
  if (!gkClaim(dir, idKey)) {
    for (let i = 0; i < 20; i++) {
      const p = gkRead(dir, idKey);
      if (p && p.result) return p.result;
      await new Promise((r) => setTimeout(r, 25));
    }
    return { send: true, surfaces, reason: null };
  }
  if (!gkClaim(dir, findKey)) {
    gkUnclaim(dir, idKey);
    return repeat();
  }
  const result = { send: true, surfaces, reason: null };
  gkWrite(dir, idKey, { result, at: t });
  gkWrite(dir, findKey, { id: candidate.id, at: t });
  return result;
}
EOF
